script.content:
@echo off
REM NitroWebExpress™ — Microsoft Defender USB Scan
REM Trigger: Windows Task Scheduler (USB drive inserted)
REM Scans all removable drives
REM Author: Max Rupplin — MEARVK LLC

echo [%date% %time%] NWE Defender USB Scan starting... >> "%~dp0\logs\defender-scan.log"

REM Scan common removable drive letters
for %%d in (D E F G H) do (
    if exist %%d:\ (
        echo Scanning %%d:\ ...
        "C:\Program Files\Windows Defender\MpCmdRun.exe" -Scan -ScanType 3 -File "%%d:\"
    )
)

echo [%date% %time%] USB Scan complete (exit=%ERRORLEVEL%) >> "%~dp0\logs\defender-scan.log"
